import 'dart:async';

void main() {
  scheduleMicrotask(() => print('microtask'));
  Timer.run(() => print('event'));
  print('sync');
}

void main() {
  print((1, 'a') == (1, 'a')); // true
  print([1, 2] == [1, 2]);     // false
}

class A {
  @override
  dynamic noSuchMethod(Invocation i) => 'missing';
}

void main() {
  dynamic a = A();
  print(a.foo()); // missing
}

final a = Future.delayed(Duration(milliseconds: 50), () => 1);
final b = Future.delayed(Duration(milliseconds: 10),
    () => throw StateError('x'));

await Future.wait([a, b]); // throws
// `a` still continues running in the background.

extension Ints on int {
  bool get isEvenish => this % 2 == 0;
}

void main() {
  Object x = 4;
  print((x as int).isEvenish); // ok
  // x.isEvenish; // not visible on Object
}

